<?php

namespace PryTax\Enums;

use Core\Enums\Interfaces\BaseEnumInterface;
use Core\Enums\Traits\BaseEnum;

/**
 * Enum InvoiceSource.
 *
 * Source of an invoice: generated by PryTax, an uploaded external PDF, or none: a virtual invoice («Без інвойсу»,
 * design.md §4.2) is a record of a payment the client made without an invoice, kept for the books only.
 *
 * @author Andrii Prykhodko <andriichello@gmail.com>
 * @package PryTax\Enums
 */
enum InvoiceSource: string implements BaseEnumInterface
{
    use BaseEnum;

    case Generated = 'generated';
    case External = 'external';
    case Virtual = 'virtual';
}
